"use client";

import "../../styles/whatiuse-base.css";
import "../../styles/components/text-field.css";
import { useId, type ComponentPropsWithRef, type ReactNode } from "react";
import { cn } from "../../lib/cn";

export type TextFieldProps = Omit<ComponentPropsWithRef<"input">, "size"> & {
  label?: string;
  description?: string;
  error?: string;
  leading?: ReactNode;
  trailing?: ReactNode;
  fieldClassName?: string;
};

export function TextField({
  id: providedId,
  label,
  description,
  error,
  leading,
  trailing,
  className,
  fieldClassName,
  ref,
  ...props
}: TextFieldProps) {
  const generatedId = useId();
  const id = providedId ?? generatedId;
  const descriptionId = description ? `${id}-description` : undefined;
  const errorId = error ? `${id}-error` : undefined;
  const describedBy = [props["aria-describedby"], descriptionId, errorId].filter(Boolean).join(" ") || undefined;

  return (
    <div className={cn("whatiuse-field", fieldClassName)} data-invalid={Boolean(error) || undefined}>
      {label && <label className="whatiuse-field__label" htmlFor={id}>{label}</label>}
      <div className="whatiuse-field__control">
        {leading && <span className="whatiuse-field__adornment" aria-hidden="true">{leading}</span>}
        <input
          ref={ref}
          id={id}
          className={cn("whatiuse-input", className)}
          aria-invalid={Boolean(error) || undefined}
          aria-describedby={describedBy}
          {...props}
        />
        {trailing && <span className="whatiuse-field__adornment">{trailing}</span>}
      </div>
      {description && <div id={descriptionId} className="whatiuse-field__description">{description}</div>}
      {error && <div id={errorId} className="whatiuse-field__error">{error}</div>}
    </div>
  );
}

/* Generated from src/foundation.css and src/styles.css. Do not edit directly. */

@layer whatiuse.tokens, whatiuse.base, whatiuse.components;

@layer whatiuse.components {
.whatiuse-field { display: grid; min-width: 0; gap: 6px; }

.whatiuse-field__label { color: var(--whatiuse-ink); font-size: 12px; font-weight: 550; }

.whatiuse-field__control { display: flex; align-items: center; height: var(--whatiuse-control-height-md); overflow: hidden; border: 1px solid var(--whatiuse-border); border-radius: var(--whatiuse-radius-control); background: var(--whatiuse-control-surface); box-shadow: var(--whatiuse-shadow-control); transition: border-color var(--whatiuse-fast), box-shadow var(--whatiuse-fast); }

.whatiuse-field[data-invalid] .whatiuse-field__control { border-color: color-mix(in oklch, var(--whatiuse-fg-danger) 46%, var(--whatiuse-control-border)); box-shadow: 0 0 0 2px color-mix(in oklch, var(--whatiuse-fg-danger) 11%, transparent); }

.whatiuse-input { width: 100%; min-width: 0; height: 100%; padding: 0 9px; border: 0; outline: 0; background: transparent; color: var(--whatiuse-ink); font-size: 13.5px; }

.whatiuse-input::placeholder { color: var(--whatiuse-fg-subtle); }

.whatiuse-input:disabled { background: var(--whatiuse-bg-subtle); color: var(--whatiuse-fg-disabled); cursor: not-allowed; }

.whatiuse-input:read-only { color: var(--whatiuse-fg-muted); }

.whatiuse-field__adornment { display: inline-flex; align-items: center; padding: 0 8px; color: var(--whatiuse-fg-subtle); }

.whatiuse-field__adornment + .whatiuse-input { padding-left: 0; }

.whatiuse-field__adornment svg { width: 14px; height: 14px; }

.whatiuse-field__adornment kbd { display: inline-flex; flex: 0 0 auto; align-items: center; justify-content: center; padding: 1px 4px; border: 1px solid var(--whatiuse-border); border-radius: 3px; background: #fafafa; color: #7b7b7b; font-family: inherit; font-size: 9px; line-height: 1; white-space: nowrap; }

.whatiuse-field__description,
.whatiuse-field__error { color: var(--whatiuse-ink-tertiary); font-size: 11.5px; line-height: 1.45; }

.whatiuse-field__error { color: var(--whatiuse-fg-danger); font-weight: 520; }

@media (forced-colors: active) {
.whatiuse-field__control { forced-color-adjust: none; border-color: CanvasText; background: Canvas; color: CanvasText; }
}

.whatiuse-field__adornment kbd { background: var(--whatiuse-subtle); color: var(--whatiuse-ink-secondary); }

:root[data-theme="dark"] .whatiuse-input:disabled { background: rgb(255 255 255 / 0.025); color: var(--whatiuse-ink-disabled); }
}
